const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.LENDLOOP_HMAC_SECRET;

function getHeader(name) {
  const lower = name.toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === lower) return String(v || '');
  }
  return '';
}

if (!secret) {
  throw new Error('LENDLOOP_HMAC_SECRET environment variable is not configured.');
}

const sigHeader = getHeader('x-lendloop-signature').trim();
const tsHeader = getHeader('x-lendloop-timestamp').trim();

let rawBody = '';
if (item.binary && item.binary.data && item.binary.data.data) {
  rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json.rawBody === 'string') {
  rawBody = item.json.rawBody;
} else {
  rawBody = JSON.stringify(item.json.body || {});
}

const nowSec = Math.floor(Date.now() / 1000);
const tsSec = Number(tsHeader);
const withinWindow = /^\d+$/.test(tsHeader) && Math.abs(nowSec - tsSec) <= 300;

let verified = false;
let reason = 'ok';

if (!sigHeader || !tsHeader) {
  reason = 'missing_headers';
} else if (!withinWindow) {
  reason = 'timestamp_out_of_window';
} else if (!sigHeader.startsWith('v1=')) {
  reason = 'invalid_signature_format';
} else {
  const providedHex = sigHeader.slice(3).toLowerCase();
  const expectedHex = crypto
    .createHmac('sha256', secret)
    .update(`${tsHeader}.${rawBody}`)
    .digest('hex');
  if (/^[0-9a-f]{64}$/.test(providedHex)) {
    const a = Buffer.from(expectedHex, 'hex');
    const b = Buffer.from(providedHex, 'hex');
    verified = a.length === b.length && crypto.timingSafeEqual(a, b);
    if (!verified) reason = 'signature_mismatch';
  } else {
    reason = 'malformed_digest';
  }
}

let payload = {};
if (verified) {
  payload = typeof item.json.body === 'object' && item.json.body !== null
    ? item.json.body
    : JSON.parse(rawBody);
}

return [
  {
    json: {
      verified,
      reason,
      payload,
    },
  },
];

const data = $input.first().json;
const event = String(data.event || 'loan.requested');
const actor = String(data.actorFirstName || 'A neighbor');
const recipient = String(data.recipientFirstName || 'Neighbor');
const tool = String(data.toolName || 'a tool');
const range = `${data.startDate} to ${data.endDate}`;

const templates = {
  'loan.requested': {
    headline: `${actor} requested ${tool} (${range})`,
    summary: `Request notification delivered to ${recipient}`,
  },
  'loan.approved': {
    headline: `${actor} approved your request for ${tool} (${range})`,
    summary: `Approval notification delivered to ${recipient}`,
  },
  'loan.declined': {
    headline: `${actor} declined your request for ${tool} (${range})`,
    summary: `Decline notification delivered to ${recipient}`,
  },
  'loan.returned': {
    headline: `${actor} marked ${tool} as returned — thanks for sharing!`,
    summary: `Return confirmation delivered to ${recipient}`,
  },
  'loan.cancelled': {
    headline: `${actor} cancelled their borrow request for ${tool} (${range})`,
    summary: `Cancellation notice delivered to ${recipient}`,
  },
};

const chosen = templates[event] || templates['loan.requested'];
const eventSuffix = event.startsWith('loan.') ? event.slice(5) : 'requested';
const idempotencyKey = String(data.eventId || `notify:${data.loanId}:${eventSuffix}`);

return [
  {
    json: {
      event,
      status: String(data.status || 'pending'),
      loanId: String(data.loanId),
      idempotencyKey,
      recipientRole: String(data.recipientRole || 'lender'),
      recipient,
      headline: chosen.headline,
      summary: chosen.summary,
      dates: range,
    },
  },
];

const crypto = require('crypto');
const composed = $('Compose Minimal Recipient Message').first().json;
const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_HMAC_SECRET environment variable is not configured.');
}

const writebackPayload = {
  loanId: composed.loanId,
  idempotencyKey: composed.idempotencyKey,
  channel: 'n8n_request_workflow',
  messageSummary: composed.summary,
};
const rawBody = JSON.stringify(writebackPayload);
const timestamp = String(Math.floor(Date.now() / 1000));
const sig = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [
  {
    json: {
      rawBody,
      timestamp,
      signature: sig,
      loanId: composed.loanId,
      event: composed.event,
    },
  },
];
